// ===========================================================================
// version.h
// - collection of version numbers
// ===========================================================================
//
// Generated by uavs3d/version.sh in the upstream repo (gitignored there).
// The vendored copy has no .git, so this is the deterministic BUILD=0 output.
// It is only used by the startup printf in uavs3d.c, never by decoding.
#ifndef __VERSION_H__
#define __VERSION_H__

#define VER_MAJOR  1                // major version number
#define VER_MINOR  2                // minor version number
#define VER_BUILD  0                // build number

#define VERSION_TYPE "release"
#define VERSION_STR  "1.2.0"
#define VERSION_SHA1 "vendored"

#endif // __VERSION_H__
